type Property = { id: string; name: string };
type Prospect = { id: string; propertyId: string; unitId: string | null; name: string; email: string; phone: string | null; desiredMoveIn: string | null; notes: string | null; status: "open" | "closed"; version: number; createdAt: string; updatedAt: string; property: Property; unit: { id: string; label: string } | null };
type ApplicationStatus = "draft" | "submitted" | "in_review" | "approved" | "rejected" | "withdrawn";
