type History = { id: string; entityType?: "prospect" | "application" | "follow_up" | "availability"; action: string; actorName: string | null; version: number; createdAt: string; reason?: string | null };
type FollowUp = { id: string; prospectId: string; kind: "tour" | "task"; title: string; dueOn: string; notes: string | null; status: "open" | "completed" | "cancelled"; version: number };
