const base = "/api/company";
const root = "/company/applications";
const encoded = encodeURIComponent;
const statuses: Record<string, string> = { draft: "Draft", submitted: "Submitted", in_review: "Under review", approved: "Approved", rejected: "Declined", withdrawn: "Withdrawn", open: "Open", closed: "Closed", completed: "Completed", cancelled: "Cancelled", unreviewed: "Not reviewed", available: "Ready", turnover: "Turnover in progress", unavailable: "Unavailable", vacant: "Vacant", occupied: "Occupied", future: "Upcoming lease" };
