  type Board = { items: Array<{ unit: { id: string; label: string; propertyId: string; status: string; property: Property }; state: string; availability: { condition: string; availableOn: string | null } | null; listing?: { forRent: boolean }; currentLease: UnitChoice["currentLease"]; nextLease: UnitChoice["nextLease"] }>; nextCursor: string | null };
  const rows = useResource<Board>(`${base}/availability?${new URLSearchParams({ propertyId, ...(search ? { q: search } : {}), ...(cursors.length ? { cursor: cursors.at(-1)! } : {}), ...(!value && initialId && !search && !cursors.length ? { unitId: initialId } : {}) })}`);
  const choices: UnitChoice[] = (rows.data?.items || []).filter(row => row.unit.status === "active").map(row => ({ unitId: row.unit.id, unitLabel: row.unit.label, propertyId: row.unit.propertyId, propertyName: row.unit.property.name, operationalStatus: row.availability?.condition === "ready" ? "available" : row.availability?.condition || "unreviewed", forRent: row.listing?.forRent === true, occupancy: row.currentLease ? "occupied" : row.nextLease ? "future" : "vacant", availableOn: row.availability?.availableOn || null, currentLease: row.currentLease, nextLease: row.nextLease }));
  useEffect(() => { if (!value && initialId) { const initial = choices.find(unit => unit.unitId === initialId); if (initial) onChange(initial); } }, [rows.data, initialId, value]);
  return <section className="applications-picker" aria-label="Choose a unit"><h3>Choose a unit</h3>{value && <p className="notice">Selected: {value.propertyName} · {value.unitLabel}</p>}<label>Find a unit<input type="search" value={q} onChange={event => { setQ(event.target.value); setCursors([]); }} maxLength={200}/></label>{!rows.data ? <Loading error={rows.error} retry={rows.reload}/> : <><ul className="applications-choice-list">{choices.map(unit => <li key={unit.unitId}><button type="button" className={`applications-choice ${value?.unitId === unit.unitId ? "selected" : "secondary"}`} aria-pressed={value?.unitId === unit.unitId} onClick={() => onChange(unit)}><strong>{unit.unitLabel}</strong><span>{label(unit.occupancy)} · {unit.forRent ? "For rent" : "Not listed for rent"} · {label(unit.operationalStatus)}</span>{unit.currentLease && <small>Current lease through {formatDate(unit.currentLease.endsOn, "open ended")}</small>}</button></li>)}</ul>{!choices.length && <p>No active units match. Review the property inventory.</p>}<div className="actions"><button type="button" className="secondary" disabled={!cursors.length} onClick={() => setCursors(old => old.slice(0, -1))}>Previous units</button><button type="button" className="secondary" disabled={!rows.data.nextCursor} onClick={() => setCursors(old => [...old, rows.data!.nextCursor!])}>Next units</button></div></>}</section>;
